[CmdletBinding()]
param(
 [Parameter(Mandatory=$true)][string]$CampaignRoot,
 [string]$VmrunPath='C:\Program Files (x86)\VMware\VMware Workstation\vmrun.exe',
 [string]$VMwareGuiPath='C:\Program Files (x86)\VMware\VMware Workstation\vmware.exe',
 [string]$WindowsVmxPath='D:\Windows 11\Windows 11.vmx',
 [string]$UbuntuVmxPath='D:\Ubuntu 24.04\Ubuntu.vmx',
 [string]$WindowsSnapshot='P5G_R4_R5_POST_MATERIALIZATION_PREEXECUTION_WINDOWS_20261013',
 [string]$UbuntuSnapshot='P5G_R4_R5_POST_MATERIALIZATION_PREEXECUTION_UBUNTU_20261013',
 [int]$PreRollSeconds=5,[int]$PostTailSeconds=10,[int]$ActiveWorkloadSeconds=60,
 [Parameter(Mandatory=$true)][ValidatePattern('^BEN_UBU_[0-9]{2}$')][string]$RunID,
 [Parameter(Mandatory=$true)][ValidateRange(1,30)][int]$GlobalOrder,
 [Parameter(Mandatory=$true)][ValidatePattern('^S(0[1-9]|1[0-5])$')][string]$ScenarioID,
 [Parameter(Mandatory=$true)][ValidateSet('A','B')][string]$Repetition,
 [Parameter(Mandatory=$true)][ValidatePattern('^U-[0-9]{2}-[AB]$')][string]$ScenarioRunID,
 [Parameter(Mandatory=$true)][ValidatePattern('^S(0[1-9]|1[0-5])-UBU-[AB]$')][string]$FixtureSeed,
 [Parameter(Mandatory=$true)][ValidateSet('TRAIN','VALIDATION','TEST')][string]$Split,
 [Parameter(Mandatory=$true)][ValidatePattern('^[A-Z0-9_]+$')][string]$ScenarioName,
 [Parameter(Mandatory=$true)][string]$LeadApplication
)
Set-StrictMode -Version 2.0;$ErrorActionPreference='Stop'
$Script:Stage='INIT';$Script:RunRoot=$null;$Script:NetworkBaseline=$null;$Script:IsolationStarted=$false
function Assert-True([bool]$Condition,[string]$Message){if(-not $Condition){throw ('SAFETY_FAILURE:'+ $Message)}}
function SHA([string]$Path){(Get-FileHash -LiteralPath $Path -Algorithm SHA256).Hash.ToLowerInvariant()}
function Write-Json([string]$Path,[object]$Object){$d=Split-Path -Parent $Path;if(-not(Test-Path -LiteralPath $d)){New-Item -ItemType Directory -Path $d -Force|Out-Null};[IO.File]::WriteAllText($Path,(($Object|ConvertTo-Json -Depth 20)+"`r`n"),(New-Object Text.UTF8Encoding($false)))}
function Write-Log([string]$Level,[string]$Message){$line='{0} [{1}] [{2}] {3}' -f [DateTime]::UtcNow.ToString('o'),$Level,$Script:Stage,$Message;Write-Host $line;if($Script:RunRoot){Add-Content -LiteralPath (Join-Path $Script:RunRoot 'UBUNTU_BENIGN_ENDURANCE_PREFLIGHT_CONTROLLER.log') -Value $line -Encoding UTF8}}
function Stage([string]$Name,[string]$Message){$Script:Stage=$Name;Write-Host '';Write-Host ('='*88) -ForegroundColor Cyan;Write-Host ('[{0}] {1}' -f $Name,$Message) -ForegroundColor Cyan;Write-Host ('='*88) -ForegroundColor Cyan;Write-Log 'INFO' $Message}
function Get-UniqueVmsd([string]$Vmx){$a=@(Get-ChildItem -LiteralPath (Split-Path -Parent $Vmx) -Filter '*.vmsd' -File);Assert-True ($a.Count -eq 1) ('VMSD_NOT_UNIQUE:'+ $Vmx);$a[0].FullName}
function Get-CurrentSnapshotName([string]$Vmx,[string]$Label){$lines=[IO.File]::ReadAllLines((Get-UniqueVmsd $Vmx));$cur='';$map=@{};foreach($l in $lines){$m=[regex]::Match($l,'^\s*snapshot\.current\s*=\s*"([^"]*)"');if($m.Success){$cur=$m.Groups[1].Value};$m=[regex]::Match($l,'^\s*snapshot(\d+)\.(uid|displayName)\s*=\s*"([^"]*)"');if($m.Success){$i=[int]$m.Groups[1].Value;if(-not$map.ContainsKey($i)){$map[$i]=@{}};$map[$i][$m.Groups[2].Value]=$m.Groups[3].Value}};Assert-True (-not[string]::IsNullOrWhiteSpace($cur)) ($Label+'_NO_CURRENT_SNAPSHOT');foreach($i in $map.Keys){if([string]$map[$i]['uid'] -ceq $cur){return [string]$map[$i]['displayName']}};throw ($Label+'_SNAPSHOT_UID_UNMAPPED')}
function Assert-CurrentSnapshot([string]$Vmx,[string]$Expected,[string]$Label){$a=Get-CurrentSnapshotName $Vmx $Label;Assert-True ($a -ceq $Expected) ($Label+'_SNAPSHOT_DRIFT expected='+$Expected+' actual='+$a)}
function Get-VmxAssignments([string]$Path){$m=@{};foreach($line in [IO.File]::ReadAllLines($Path)){$x=[regex]::Match($line,'^\s*([^#][^=]*?)\s*=\s*"([^"]*)"\s*$');if($x.Success){$m[$x.Groups[1].Value.Trim().ToLowerInvariant()]=$x.Groups[2].Value}};$m}
function Assert-VmxHardening([string]$Label,[string]$Path){$a=Get-VmxAssignments $Path;$req=[ordered]@{'isolation.tools.copy.disable'='TRUE';'isolation.tools.paste.disable'='TRUE';'isolation.tools.dnd.disable'='TRUE';'isolation.tools.hgfs.disable'='TRUE';'sharedfolder.maxnum'='0';'sharedfolder0.enabled'='FALSE';'sharedfolder0.present'='FALSE';'sharedfolder0.readaccess'='FALSE';'sharedfolder0.writeaccess'='FALSE';'ethernet0.startconnected'='FALSE';'usb.present'='FALSE'};foreach($k in $req.Keys){Assert-True $a.ContainsKey($k) ($Label+'_VMX_MISSING_'+$k);Assert-True ([string]$a[$k] -ceq [string]$req[$k]) ($Label+'_VMX_DRIFT_'+$k+'='+$a[$k])}}
function Disable-HostNetwork([object]$Baseline){$ups=@($Baseline.PhysicalAdapters|Where-Object{$_.InitialStatus -ceq 'Up'});Assert-True ($ups.Count -ge 1) 'NO_UP_PHYSICAL_ADAPTER';foreach($a in $ups){Disable-NetAdapter -Name ([string]$a.Name) -Confirm:$false -ErrorAction Stop};Start-Sleep -Seconds 3;$Script:IsolationStarted=$true;$v4=@(Get-NetRoute -AddressFamily IPv4 -ErrorAction SilentlyContinue|Where-Object{$_.DestinationPrefix -eq '0.0.0.0/0'});$v6=@(Get-NetRoute -AddressFamily IPv6 -ErrorAction SilentlyContinue|Where-Object{$_.DestinationPrefix -eq '::/0'});Assert-True ($v4.Count -eq 0) 'IPV4_DEFAULT_ROUTE_REMAINS';Assert-True ($v6.Count -eq 0) 'IPV6_DEFAULT_ROUTE_REMAINS';Write-Json (Join-Path $Script:RunRoot 'evidence\HOST_ISOLATION_PROOF.json') ([ordered]@{status='PASS';disabled_adapters=@($ups.Name);ipv4_default_route_count=$v4.Count;ipv6_default_route_count=$v6.Count;timestamp=[DateTime]::UtcNow.ToString('o')})}
function Restore-HostNetwork([object]$Baseline){
    foreach($a in @($Baseline.PhysicalAdapters)){
        if([string]$a.InitialStatus -ceq 'Up'){
            Enable-NetAdapter -Name ([string]$a.Name) -Confirm:$false -ErrorAction Stop
        }
    }

    # Allow bounded adapter-state convergence after enable/re-enumeration. Recovery
    # does not require network association, DHCP, a default route, or Internet access.
    $deadline=[DateTime]::UtcNow.AddSeconds(300)
    $attempt=0
    $consecutiveRestored=0
    $last='NOT_TESTED'
    do{
        Start-Sleep -Seconds 2
        $attempt++
        $cur=Get-P5GNetworkBaseline -AttemptID $Script:AttemptID -RunID $RunID
        $check=Test-P5GNetworkRestored $Baseline $cur.PhysicalAdapters $cur.Routes ([pscustomobject]@{vms_safe=$true})
        if([bool]$check.restored){
            $consecutiveRestored++
            if($consecutiveRestored -ge 3){
                Write-Host ('NETWORK ADAPTER RESTORE CONFIRMED: attempts='+$attempt+' consecutive_restored='+$consecutiveRestored) -ForegroundColor Green
                return $cur
            }
        } else {
            $consecutiveRestored=0
            $last=[string]$check.reason
            if(($attempt % 10) -eq 0){
                Write-Host ('NETWORK ADAPTER RESTORE WAITING: attempts='+$attempt+' last_reason='+$last) -ForegroundColor Yellow
            }
        }
    }while([DateTime]::UtcNow -lt $deadline)
    throw ('NETWORK_ADAPTER_RESTORE_NOT_CONFIRMED:attempts='+$attempt+':last_reason='+$last)
}
function Open-VMwareGuiTab([string]$Vmx,[string]$Label){Write-Log 'INFO' ('opening VMware GUI tab: '+$Label);[void](Start-Process -FilePath $VMwareGuiPath -ArgumentList ('"'+$Vmx+'"') -WindowStyle Normal -PassThru)}
try{Add-Type -AssemblyName UIAutomationClient -ErrorAction Stop;Add-Type -AssemblyName UIAutomationTypes -ErrorAction Stop}catch{throw ('UIAUTOMATION_UNAVAILABLE:'+ $_.Exception.Message)}
function Get-VmwareLockOwnerPid{ $owners=New-Object 'Collections.Generic.List[int]';foreach($v in @($WindowsVmxPath,$UbuntuVmxPath)){$lck=$v+'.lck';if(-not(Test-Path -LiteralPath $lck -PathType Container)){continue};foreach($f in @(Get-ChildItem -LiteralPath $lck -File -ErrorAction SilentlyContinue)){$txt='';try{$txt=Get-Content -LiteralPath $f.FullName -Raw -ErrorAction SilentlyContinue}catch{};$m=[regex]::Match([string]$txt,'(\d{3,6})-\d+\(vmware\.exe\)');if($m.Success){$pid2=[int]$m.Groups[1].Value;if(-not$owners.Contains($pid2)){$owners.Add($pid2)}}}};return @($owners.ToArray()) }
function Get-WorkstationTabNames{ $procs=@(Get-Process -Name 'vmware' -ErrorAction SilentlyContinue|Where-Object{$_.MainWindowHandle -ne 0});if($procs.Count -eq 0){return @()};$owners=@(Get-VmwareLockOwnerPid);$ordered=@();foreach($o in $owners){$ordered+=@($procs|Where-Object{$_.Id -eq $o})};$ordered+=@($procs|Where-Object{$owners -notcontains $_.Id});foreach($proc in $ordered){$root=$null;try{$root=[System.Windows.Automation.AutomationElement]::FromHandle($proc.MainWindowHandle)}catch{};if($null -eq $root){continue};$walker=[System.Windows.Automation.TreeWalker]::RawViewWalker;$stack=New-Object System.Collections.Stack;$stack.Push($root);$found=New-Object 'Collections.Generic.List[string]';$guard=0;while($stack.Count -gt 0 -and $guard -lt 3000){$guard++;$e=$stack.Pop();$cls='';try{$cls=[string]$e.Current.ClassName}catch{};if($cls -ceq 'vmware.TabStrip'){$ch=$walker.GetFirstChild($e);while($null -ne $ch){$ccls='';try{$ccls=[string]$ch.Current.ClassName}catch{};if($ccls -ceq 'CNoFlickerButton'){$nm='';try{$nm=[string]$ch.Current.Name}catch{};if(-not[string]::IsNullOrWhiteSpace($nm)){$found.Add($nm)}};$ch=$walker.GetNextSibling($ch)}};$kid=$walker.GetFirstChild($e);while($null -ne $kid){$stack.Push($kid);$kid=$walker.GetNextSibling($kid)}};if($found.Count -gt 0){return @($found.ToArray()|Sort-Object -Unique)}};return @() }
function Remove-RogueVmwareInstances{ $owners=@(Get-VmwareLockOwnerPid);foreach($proc in @(Get-Process -Name 'vmware' -ErrorAction SilentlyContinue)){if($owners -contains $proc.Id){continue};try{$proc|Stop-Process -Force -ErrorAction SilentlyContinue}catch{}};Start-Sleep -Milliseconds 500 }
function Ensure-GuiEntries{ $beforeW=Get-VmOn $VmrunPath $WindowsVmxPath;$beforeU=Get-VmOn $VmrunPath $UbuntuVmxPath;$names=@(Get-WorkstationTabNames);if($names -notcontains 'Windows 11'){Open-VMwareGuiTab $WindowsVmxPath 'Windows'};$names=@(Get-WorkstationTabNames);if($names -notcontains 'Ubuntu'){Open-VMwareGuiTab $UbuntuVmxPath 'Ubuntu'};Start-Sleep -Seconds 2;Remove-RogueVmwareInstances;$final=@(Get-WorkstationTabNames);Assert-True ($final -contains 'Windows 11') 'WINDOWS_GUI_TAB_NOT_VISIBLE';Assert-True ($final -contains 'Ubuntu') 'UBUNTU_GUI_TAB_NOT_VISIBLE';Assert-True ((Get-VmOn $VmrunPath $WindowsVmxPath) -eq $beforeW) 'GUI_ATTACH_CHANGED_WINDOWS_POWER';Assert-True ((Get-VmOn $VmrunPath $UbuntuVmxPath) -eq $beforeU) 'GUI_ATTACH_CHANGED_UBUNTU_POWER' }
function New-RunManifest([string]$Root){$rows=@();foreach($f in Get-ChildItem -LiteralPath $Root -Recurse -File|Sort-Object FullName){if($f.Name -in @('PACKAGE_MANIFEST.csv','RUN_FULL_VERIFICATION.json')){continue};$rows+=[pscustomobject]@{relative_path=$f.FullName.Substring($Root.Length+1);bytes=$f.Length;sha256=(SHA $f.FullName)}};$p=Join-Path $Root 'PACKAGE_MANIFEST.csv';$rows|Export-Csv -LiteralPath $p -NoTypeInformation -Encoding UTF8;return $p}

$PackageRoot=$PSScriptRoot
. (Join-Path $PackageRoot 'NetworkBaseline.ps1')
. (Join-Path $PackageRoot 'UbuntuNativeBridge.ps1')
$principal=New-Object Security.Principal.WindowsPrincipal([Security.Principal.WindowsIdentity]::GetCurrent());Assert-True ($principal.IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)) 'ADMINISTRATOR_POWERSHELL_REQUIRED'
foreach($p in @($CampaignRoot,$VmrunPath,$VMwareGuiPath,$WindowsVmxPath,$UbuntuVmxPath)){Assert-True (Test-Path -LiteralPath $p) ('REQUIRED_PATH_MISSING:'+ $p)}
Assert-VmxHardening 'Windows' $WindowsVmxPath;Assert-VmxHardening 'Ubuntu' $UbuntuVmxPath
Assert-True (-not(Get-VmOn $VmrunPath $WindowsVmxPath)) 'WINDOWS_MUST_BE_OFF_PRE_RUN';Assert-True (-not(Get-VmOn $VmrunPath $UbuntuVmxPath)) 'UBUNTU_MUST_BE_OFF_PRE_RUN'
Assert-CurrentSnapshot $WindowsVmxPath $WindowsSnapshot 'Windows';Assert-CurrentSnapshot $UbuntuVmxPath $UbuntuSnapshot 'Ubuntu'
$Script:AttemptID=[guid]::NewGuid().ToString('N').Substring(0,16);$stamp=Get-Date -Format 'yyyyMMdd_HHmmss';$Script:RunRoot=Join-Path $CampaignRoot ('03_UBUNTU\BENIGN\qualification\endurance_v28\'+$RunID+'_'+$Script:AttemptID+'_'+$stamp);New-Item -ItemType Directory -Path $Script:RunRoot -Force|Out-Null;foreach($d in @('evidence','recovery')){New-Item -ItemType Directory -Path (Join-Path $Script:RunRoot $d) -Force|Out-Null}
$Overall=[Diagnostics.Stopwatch]::StartNew();$runSucceeded=$false;$recoverySucceeded=$false;$mainError='';$recoveryError=''
try{
 Stage 'PRESTATE' 'Verify exact snapshots, hardening, VM state, and VMware GUI entries';Ensure-GuiEntries;$Script:NetworkBaseline=Get-P5GNetworkBaseline -AttemptID $Script:AttemptID -RunID $RunID;Write-Json (Join-Path $Script:RunRoot 'recovery\network_baseline.json') $Script:NetworkBaseline
 Stage 'ISOLATION' 'Disable baseline physical adapters and require zero IPv4/IPv6 default routes';Disable-HostNetwork $Script:NetworkBaseline
 Stage 'VM_START' 'Power on Ubuntu by native VIX; Windows remains OFF';Start-UbuntuVM $VmrunPath $UbuntuVmxPath;Assert-True (-not(Get-VmOn $VmrunPath $WindowsVmxPath)) 'WINDOWS_POWERED_ON_UNEXPECTEDLY';Ensure-GuiEntries
 $guestHelper='/tmp/UBUNTU_Guest_Official_'+$RunID+'_'+$Script:AttemptID+'.sh';$guestTrace='/tmp/UBUNTU_Compound_Trace_'+$Script:AttemptID+'.bt';$guestCred='/tmp/UBUNTU_BENIGN_OFFICIAL_'+$RunID+'_'+$Script:AttemptID+'.sudo';$guestRunRoot='/tmp/benign_official/'+$RunID+'/'+$Script:AttemptID;$guestArchive='/tmp/UBUNTU_BENIGN_OFFICIAL_'+$RunID+'_'+$Script:AttemptID+'.tar.gz'
 Stage 'HELPER_TRANSFER' 'Transfer Ubuntu compound workload and telemetry helpers by native VIX';Copy-ToUbuntuGuest (Join-Path $PackageRoot 'UBUNTU_Guest_Official.sh') $guestHelper;Copy-ToUbuntuGuest (Join-Path $PackageRoot 'UBUNTU_Guest_Qualification_V6_BASE.sh') ($guestHelper+'.v6base');Copy-ToUbuntuGuest (Join-Path $PackageRoot 'UBUNTU_BENIGN_SCENARIO_DISPATCHER_V1.sh') ($guestHelper+'.scenario');Copy-ToUbuntuGuest (Join-Path $PackageRoot 'UBUNTU_Compound_Trace.bt') $guestTrace;New-UbuntuSudoCredentialFile $guestCred|Out-Null
 Stage 'WORKLOAD_PREPARE' 'Create deterministic fixture and paused five-task compound root process';$rc=Invoke-UbuntuGuestProgram '/bin/bash' "$guestHelper prepare $($Script:AttemptID) $guestRunRoot $ActiveWorkloadSeconds $guestCred ubuntu $ScenarioID $Repetition $ScenarioRunID $FixtureSeed $Split $ScenarioName $LeadApplication $RunID $GlobalOrder" 300;Assert-True ($rc -eq 0) 'UBUNTU_WORKLOAD_PREPARE_FAILED';Copy-FromUbuntuGuest ($guestRunRoot+'/evidence/workload_prepare_receipt.json') (Join-Path $Script:RunRoot 'evidence\workload_prepare_receipt.json')
 Stage 'TELEMETRY_START' 'Start bpftrace process-tree/file telemetry plus auditd verification before workload';$rc=Invoke-UbuntuGuestProgram '/bin/bash' "$guestHelper telemetry_start $($Script:AttemptID) $guestRunRoot $guestTrace $guestCred ubuntu $ScenarioID $Repetition $ScenarioRunID $FixtureSeed $Split $ScenarioName $LeadApplication $RunID $GlobalOrder" 300;Assert-True ($rc -eq 0) 'UBUNTU_TELEMETRY_START_FAILED';Copy-FromUbuntuGuest ($guestRunRoot+'/evidence/telemetry_prepare_receipt.json') (Join-Path $Script:RunRoot 'evidence\telemetry_prepare_receipt.json');$tp=Get-Content (Join-Path $Script:RunRoot 'evidence\telemetry_prepare_receipt.json') -Raw|ConvertFrom-Json;Assert-True ([string]$tp.status -ceq 'PASS' -and [bool]$tp.telemetry_ready) 'UBUNTU_TELEMETRY_NOT_READY';Write-Host '*** TELEMETRY READY ***' -ForegroundColor Green;Start-Sleep -Seconds $PreRollSeconds
 Stage 'WORKLOAD_RUN' 'Execute 60-second Ubuntu compound hard-negative process tree';$rc=Invoke-UbuntuGuestProgram '/bin/bash' "$guestHelper workload_run $($Script:AttemptID) $guestRunRoot $ActiveWorkloadSeconds $guestCred ubuntu $ScenarioID $Repetition $ScenarioRunID $FixtureSeed $Split $ScenarioName $LeadApplication $RunID $GlobalOrder" 120;Assert-True ($rc -eq 0) 'UBUNTU_WORKLOAD_RUN_FAILED';Copy-FromUbuntuGuest ($guestRunRoot+'/evidence/workload_run_receipt.json') (Join-Path $Script:RunRoot 'evidence\workload_run_receipt.json');$wr=Get-Content (Join-Path $Script:RunRoot 'evidence\workload_run_receipt.json') -Raw|ConvertFrom-Json;Assert-True ([string]$wr.status -ceq 'PASS') 'UBUNTU_WORKLOAD_RECEIPT_FAIL';Assert-True ([double]$wr.active_duration_seconds -ge 60 -and [double]$wr.active_duration_seconds -le 65) 'UBUNTU_ACTIVE_DURATION_OUT_OF_RANGE';Assert-True ([double]$wr.root_lifecycle_seconds -le 70) 'UBUNTU_ROOT_LIFECYCLE_EXCESSIVE';Assert-True ([int]$wr.compound_task_count -ge 5) 'UBUNTU_TASK_COUNT_TOO_LOW';Write-Host ('WORKLOAD COMPLETE: ROOT_PID='+$wr.root_pid+' ACTIVE_DURATION='+$wr.active_duration_seconds+'s ROOT_LIFECYCLE='+$wr.root_lifecycle_seconds+'s') -ForegroundColor Green
 Stage 'TELEMETRY_FINALIZE' 'Stop bpftrace after post-tail and export auditd verification evidence';$rc=Invoke-UbuntuGuestProgram '/bin/bash' "$guestHelper telemetry_finalize $($Script:AttemptID) $guestRunRoot $PostTailSeconds $guestCred ubuntu" 180;Assert-True ($rc -eq 0) 'UBUNTU_TELEMETRY_FINALIZE_FAILED';Copy-FromUbuntuGuest ($guestRunRoot+'/evidence/telemetry_capture_receipt.json') (Join-Path $Script:RunRoot 'evidence\telemetry_capture_receipt.json');$tr=Get-Content (Join-Path $Script:RunRoot 'evidence\telemetry_capture_receipt.json') -Raw|ConvertFrom-Json;Assert-True ([string]$tr.status -ceq 'PASS') 'UBUNTU_TELEMETRY_CAPTURE_FAIL';Write-Host ('REAL TELEMETRY: ROWS='+$tr.telemetry_rows+' AUDIT_EXEC_BYTES='+$tr.audit_exec_bytes+' AUDIT_FILE_BYTES='+$tr.audit_file_bytes) -ForegroundColor Green
 Stage 'GUEST_PACK' 'Hash and fast-compress bpftrace, auditd, workload and lifecycle evidence inside Ubuntu';$rc=Invoke-UbuntuGuestProgram '/bin/bash' "$guestHelper pack $($Script:AttemptID) $guestRunRoot $guestArchive $guestCred ubuntu" 240;Assert-True ($rc -eq 0) 'UBUNTU_GUEST_PACK_FAILED';Copy-FromUbuntuGuest ($guestRunRoot+'/evidence/guest_pack_receipt.json') (Join-Path $Script:RunRoot 'evidence\guest_pack_receipt.json');$pr=Get-Content (Join-Path $Script:RunRoot 'evidence\guest_pack_receipt.json') -Raw|ConvertFrom-Json
 Stage 'ARCHIVE_TRANSFER' 'Transfer compressed archive only; no loose raw bulk telemetry crosses to host';$hostArchive=Join-Path $Script:RunRoot 'capture_archive.tar.gz';Copy-FromUbuntuGuest $guestArchive $hostArchive 600;Assert-True ((SHA $hostArchive) -ceq [string]$pr.archive_sha256) 'UBUNTU_ARCHIVE_SHA_MISMATCH';$listing=@(& tar -tzf $hostArchive 2>&1);Assert-True ($LASTEXITCODE -eq 0) 'UBUNTU_ARCHIVE_LIST_FAILED';foreach($n in @('evidence/bpftrace.csv','evidence/audit_exec.log','evidence/audit_file.log','evidence/workload_run_receipt.json','evidence/telemetry_capture_receipt.json','evidence/SHA256SUMS.txt')){Assert-True (@($listing|Where-Object{$_ -ceq $n}).Count -eq 1) ('UBUNTU_ARCHIVE_ENTRY_MISSING:'+ $n)}
 $runSucceeded=$true
}catch{$mainError=$_.Exception.Message;Write-Host ('ENDURANCE PREFLIGHT EXECUTION ERROR: '+$mainError) -ForegroundColor Red}
finally{
 Stage 'RECOVERY' 'Stop Ubuntu, revert exact frozen snapshot, verify Windows unchanged, restore host network and VMware GUI entries'
 try{try{Stop-UbuntuVM $VmrunPath $UbuntuVmxPath}catch{Write-Log 'WARN' ('Stop error: '+$_.Exception.Message)};Revert-UbuntuExactSnapshot $VmrunPath $UbuntuVmxPath $UbuntuSnapshot;Assert-True (-not(Get-VmOn $VmrunPath $UbuntuVmxPath)) 'UBUNTU_RUNNING_AFTER_RECOVERY';Assert-True (-not(Get-VmOn $VmrunPath $WindowsVmxPath)) 'WINDOWS_RUNNING_AFTER_RECOVERY';Assert-CurrentSnapshot $UbuntuVmxPath $UbuntuSnapshot 'Ubuntu';Assert-CurrentSnapshot $WindowsVmxPath $WindowsSnapshot 'Windows';if($Script:IsolationStarted){$null=Restore-HostNetwork $Script:NetworkBaseline};Ensure-GuiEntries;Write-Json (Join-Path $Script:RunRoot 'recovery\POST_RECOVERY_VERIFICATION.json') ([ordered]@{status='PASS';ubuntu_off=$true;windows_off=$true;ubuntu_snapshot=(Get-CurrentSnapshotName $UbuntuVmxPath 'Ubuntu');windows_snapshot=(Get-CurrentSnapshotName $WindowsVmxPath 'Windows');network_restored=$true;gui_entries_restored=$true;timestamp=[DateTime]::UtcNow.ToString('o')});$recoverySucceeded=$true}catch{$recoveryError=$_.Exception.Message;Write-Host ('RECOVERY ERROR: '+$recoveryError) -ForegroundColor Red};try{Close-UbuntuVix}catch{}
}
if(-not$runSucceeded -or -not$recoverySucceeded){Write-Json (Join-Path $Script:RunRoot 'RUN_RESULT.json') ([ordered]@{status='FAIL';qualification_only=$true;official_run=$false;endurance_preflight=$true;official_campaign_slots_consumed=0;run_id=$RunID;global_order=$GlobalOrder;scenario_id=$ScenarioID;scenario_name=$ScenarioName;split=$Split;repetition=$Repetition;scenario_run_id=$ScenarioRunID;fixture_seed=$FixtureSeed;lead_application=$LeadApplication;execution_error=$mainError;recovery_error=$recoveryError;run_root=$Script:RunRoot});throw ('UBUNTU_BENIGN_ENDURANCE_PREFLIGHT_FAIL run_id='+$RunID+' execution='+$mainError+' recovery='+$recoveryError)}
Stage 'PACKAGE_VERIFY' 'Create complete run manifest and verify all listed evidence hashes';$Overall.Stop();Write-Json (Join-Path $Script:RunRoot 'RUN_RESULT.json') ([ordered]@{status='PASS';qualification_only=$true;official_run=$false;endurance_preflight=$true;official_campaign_slots_consumed=0;run_id=$RunID;global_order=$GlobalOrder;scenario_id=$ScenarioID;scenario_name=$ScenarioName;split=$Split;repetition=$Repetition;scenario_run_id=$ScenarioRunID;fixture_seed=$FixtureSeed;lead_application=$LeadApplication;ground_truth='BENIGN';workload=($ScenarioID+'_'+$ScenarioName+'_SCENARIO_AWARE_V27');telemetry='bpftrace_primary_plus_auditd_verification';workload_duration_seconds=[double]$wr.active_duration_seconds;total_run_seconds=[Math]::Round($Overall.Elapsed.TotalSeconds,3);run_root=$Script:RunRoot;timestamp=[DateTime]::UtcNow.ToString('o')});$manifest=New-RunManifest $Script:RunRoot;$rows=@(Import-Csv $manifest);$fail=0;foreach($row in $rows){$p=Join-Path $Script:RunRoot $row.relative_path;if((-not (Test-Path -LiteralPath $p -PathType Leaf)) -or ((SHA $p) -cne [string]$row.sha256)){$fail++}};Write-Json (Join-Path $Script:RunRoot 'RUN_FULL_VERIFICATION.json') ([ordered]@{status=$(if($fail-eq0){'PASS'}else{'FAIL'});fail=$fail;manifest_sha256=(SHA $manifest)});Assert-True ($fail -eq 0) 'UBUNTU_PREFLIGHT_PACKAGE_SELF_VERIFICATION_FAILED';Write-Host '';Write-Host ('FINAL UBUNTU ENDURANCE PREFLIGHT PASS: '+$RunID) -ForegroundColor Green;Write-Host ('Evidence package: '+$Script:RunRoot) -ForegroundColor Green;Write-Host ('Official campaign slots consumed: 0; endurance preflight run_id='+$RunID) -ForegroundColor Yellow;Write-Host ('TOTAL PREFLIGHT RUN SECONDS: '+$Overall.Elapsed.TotalSeconds.ToString('F1')) -ForegroundColor Green;$Script:RunRoot
